1	function task015_public_case()
2	% Public symptom-level reproduction using a real Spinach system and pipeline.
3	formalisms={'sphten-liouv','zeeman-liouv'};
4	methods={'dibari','IME'};
5	
6	for f=1:numel(formalisms)
7	    for k=1:numel(methods)
8	        formalism=formalisms{f};
9	        method=methods{k};
10	
11	        try
12	            spin_system=task015_public_system(formalism);
13	            % Assemble the system's isotropic Zeeman and scalar-coupling
14	            % Hamiltonian through Spinach's operator interface. This keeps
15	            % the physical input active while avoiding MATLAB's table-only
16	            % descriptor assembly in the GNU Octave benchmark image.
17	            HLSPS=physical_left_hamiltonian(spin_system);
18	            rho_eq=equilibrium(spin_system,HLSPS);
19	            R=relaxation(spin_system);
20	
21	            if strcmp(method,'IME')
22	                Rt=thermalize(spin_system,R,[],[],rho_eq,'IME');
23	            else
24	                Rt=thermalize(spin_system,R,HLSPS,...
25	                              spin_system.rlx.temperature,[],method);
26	            end
27	
28	            fixed_residual=norm(Rt*rho_eq,2);
29	            evolved=step(spin_system,1i*Rt,rho_eq,0.01);
30	            trajectory_residual=norm(evolved-rho_eq,2);
31	
32	            coil=state(spin_system,'Lz','19F');
33	            signal_before=trace(coil'*rho_eq);
34	            signal_after=trace(coil'*evolved);
35	            observable_residual=abs(signal_after-signal_before);
36	
37	            % Report two qualitative scientific diagnostics in addition to
38	            % the fixed-point symptom.  The first uses the physical trace
39	            % functional in Zeeman coordinates and the canonical scalar
40	            % population in spherical-tensor coordinates.  The second asks
41	            % whether a traceless longitudinal response retains the declared
42	            % non-selective damping rate after basis selection.
43	            if strcmp(formalism,'zeeman-liouv')
44	                d=prod(spin_system.comp.mults);
45	                identity=eye(d); identity=identity(:);
46	                population=identity'*rho_eq;
47	            else
48	                population=unit_state(spin_system)'*rho_eq;
49	            end
50	            probe=state(spin_system,'Lz','19F');
51	            response_rate=-real(probe'*R*probe)/(probe'*probe);
52	            normalization_residual=abs(population-1);
53	            response_residual=abs(response_rate-spin_system.rlx.damp_rate);
54	
55	            fprintf('TASK015_CASE|%s|%s|%d|ok|%s|%s|%s|%s|%s\n',...
56	                    formalism,method,numel(rho_eq),...
57	                    category(fixed_residual),category(trajectory_residual),...
58	                    category(observable_residual),category(normalization_residual),...
59	                    category(response_residual));
60	        catch err
61	            message=strrep(err.message,'|','/');
62	            message=strrep(message,sprintf('\n'),' ');
63	            fprintf('TASK015_CASE|%s|%s|0|error|nonfinite|nonfinite|nonfinite|nonfinite|nonfinite|%s\n',...
64	                    formalism,method,message);
65	        end
66	    end
67	end
68	end
