% Probe current zeeman-liouv behavior in detail
spin_system=task015_public_system('zeeman-liouv');
d=prod(spin_system.comp.mults);
N=d^2;
fprintf('d=%d N=%d dim-state=%d\n',d,N,numel(unit_state(spin_system)));

% Unit states under both conventions
u_cur=unit_state(spin_system);                     % current snapshot
u_un=sparse(eye(d)); u_un=u_un(:);                 % un-normalized stretched identity
fprintf('norm(u_cur)=%g dot(u_cur,u_un)=%g\n',norm(u_cur),dot(u_cur,u_un));

R=relaxation(spin_system);
fprintf('R: nnz=%d isdiag=%d\n',nnz(R),nnz(R)==nnz(diag(diag(R))));
fprintf('norm(R*u_cur)=%g norm(R*u_un)=%g\n',norm(R*u_cur),norm(R*u_un));

% probe = vec(Lz_total)
probe=state(spin_system,'Lz','19F');
fprintf('probe: nnz=%d dot(probe,u_un)=%g probe''*probe=%g\n',nnz(probe),dot(probe,u_un),probe'*probe);
fprintf('response rate = %g (target %g)\n',-real(probe'*R*probe)/(probe'*probe), spin_system.rlx.damp_rate);

% support analysis
idx_id=find(u_un~=0);
fprintf('u support size=%d ; probe support size=%d ; probe support subset of u support: %d\n',...
    numel(idx_id),nnz(probe),all(find(probe)~=0 & ~ismember(find(probe),idx_id))==0);
dr=diag(R);
fprintf('diag(R) at id positions: min=%g max=%g\n',min(dr(idx_id)),max(dr(idx_id)));
fprintf('diag(R) at other positions: min=%g max=%g\n',min(dr(setdiff(1:N,idx_id))),max(dr(setdiff(1:N,idx_id))));

% equilibrium state conventions
HLSPS=physical_left_hamiltonian_probe(spin_system);
rho_eq=equilibrium(spin_system,HLSPS);
fprintf('identity-population of rho_eq = %g ; u_cur''*rho_eq = %g\n',u_un'*rho_eq, u_cur'*rho_eq);
fprintf('norm(rho_eq)=%g nnz(rho_eq)=%d\n',norm(rho_eq),nnz(rho_eq));

function H=physical_left_hamiltonian_probe(spin_system)
nspins=spin_system.comp.nspins;
H=0*operator(spin_system,'E',1,'left');
for n=1:nspins
    omega=trace(spin_system.inter.zeeman.matrix{n})/3;
    H=H+omega*operator(spin_system,'Lz',n,'left');
end
axes={'Lx','Ly','Lz'};
for n=1:nspins
    for k=(n+1):nspins
        if isempty(spin_system.inter.coupling.matrix{n,k}), continue; end
        coupling=trace(spin_system.inter.coupling.matrix{n,k})/3;
        for a=1:numel(axes)
            H=H+coupling*operator(spin_system,{axes{a},axes{a}},{n,k},'left');
        end
    end
end
end

