function probe4()
% Cross-representation agreement: same physical observables from both bases
opspec={{'Lz',1},{'Lz',2},{'Lz',3},{'Lz',4},{'L+',1}};
vals=zeros(numel(opspec),2);
formalisms={'sphten-liouv','zeeman-liouv'};
for f=1:numel(formalisms)
    spin_system=task015_public_system(formalisms{f});
    H=phys_ham(spin_system);
    rho_eq=equilibrium(spin_system,H);
    n=opspec{f};
    for k=1:numel(opspec)
        n=opspec{k};
        probe=state(spin_system,n(1),n(2));
        vals(k,f)=real(probe'*rho_eq);
    end
end
for k=1:numel(opspec)
    fprintf('%s spin %d: sphten=%+.10e zeeman=%+.10e diff=%.3e\n',...
        opspec{k}{1},opspec{k}{2},vals(k,1),vals(k,2),abs(vals(k,1)-vals(k,2)));
end
end

function H=phys_ham(spin_system)
nspins=spin_system.comp.nspins;
H=0*operator(spin_system,'E',1,'left');
for n=1:nspins
    omega=trace(spin_system.inter.zeeman.matrix{n})/3;
    H=H+omega*operator(spin_system,'Lz',n,'left');
end
axes={'Lx','Ly','Lz'};
for n=1:nspins
    for k=(n+1):nspins
        if isempty(spin_system.inter.coupling.matrix{n,k}), continue; end
        coupling=trace(spin_system.inter.coupling.matrix{n,k})/3;
        for a=1:numel(axes)
            H=H+coupling*operator(spin_system,{axes{a},axes{a}},{n,k},'left');
        end
    end
end
end
